-- Devin CLI 3000.10.21 schema from TokenTracker test/devin-parser.test.js:47-90 (MIT (c) 2026 xiufengsun).
-- Rows 1-5 :360-454 (three replays of req-a, then req-b), 6-7 :456-493 (cross-session fork), 8-9 :495-543
-- (corrected sibling), 10-11 :545-624 (pending and no request_id), 12-14 :626-686 (per-request models),
-- 15-16 :688-724 (Z and +00:00). Row 17: tokscale sessions/devin.rs:678-714 (MIT (c) 2025 Junho Yeo), no request_id.
CREATE TABLE sessions (id TEXT PRIMARY KEY, working_directory TEXT, backend_type TEXT, model TEXT, agent_mode TEXT,
  created_at INTEGER, last_activity_at INTEGER, title TEXT, main_chain_id INTEGER, shell_last_seen_index INTEGER,
  cogs_json TEXT, workspace_dirs TEXT, hidden INTEGER, metadata TEXT);
CREATE TABLE message_nodes (row_id INTEGER PRIMARY KEY, session_id TEXT, node_id INTEGER, parent_node_id INTEGER,
  chat_message TEXT, created_at INTEGER, metadata TEXT);
CREATE TABLE subagent_heads (session_id TEXT, agent_id TEXT, chain_node_id INTEGER, updated_at INTEGER,
  PRIMARY KEY (session_id, agent_id));
